import{c as t,Q as r,j as a,m as s}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse(`{"title":"Connecting other software: Manager's network interfaces","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/http-interfaces.md","filePath":"user/reference/http-interfaces.md"}`),n={name:"user/reference/http-interfaces.md"};function o(d,e,i,c,h,l){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="connecting-other-software-manager-s-network-interfaces" tabindex="-1">Connecting other software: Manager&#39;s network interfaces <a class="header-anchor" href="#connecting-other-software-manager-s-network-interfaces" aria-label="Permalink to &quot;Connecting other software: Manager&#39;s network interfaces&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and club IT volunteers connecting other software — a results website, a federation system, a script, an AI app — to meshO Manager.</p><p><strong>Every HTTP interface Manager has is listed, live, at <code>http://&lt;server&gt;/swagger</code></strong> — on the server computer, <code>http://localhost:5154/swagger</code>. It is generated by the running Manager itself, so it is always complete and always matches the version you have: every address under <code>/manager/api/</code>, grouped by area, with the parameters each takes and what it returns, and a <strong>Try it out</strong> button that sends a real request. Software that reads an API description can fetch the same list as an OpenAPI document from <code>http://&lt;server&gt;/swagger/v1/swagger.json</code>.</p><h2 id="the-full-list-swagger" tabindex="-1">The full list: /swagger <a class="header-anchor" href="#the-full-list-swagger" aria-label="Permalink to &quot;The full list: /swagger&quot;">​</a></h2><p>The list is open to anyone who can reach the server. Trying an address out is not: it goes through the same rules as any other request, so anything that changes the event — a <code>POST</code>, <code>PATCH</code> or <code>DELETE</code> — needs the <a href="./settings#access-protection">access PIN</a> once one is set, and you sign in by opening <code>/manager</code> in the same browser first. <strong>Try it out</strong> on such an address changes your event for real; use a copy of the event if you are experimenting.</p><p>Most of those addresses are the plumbing between Manager&#39;s own screens and the server, and they can change from one release to the next. Two kinds are kept stable for other software to build on: the <a href="#files-other-software-can-fetch">files other software can fetch</a> and the <a href="./ai-assistants-mcp">MCP</a> endpoint. The rest of this page covers those, and the things Swagger can&#39;t show: the screens people open in a browser, radio punches over TCP, and the connections Manager makes out to other servers.</p><p>All of it goes out on one web server — <strong>port 5154</strong> over HTTP, and <strong>5155</strong> over HTTPS once <a href="./https-and-certificates">HTTPS</a> is on (both can be changed in <strong>Settings → <a href="./settings#server">Server</a></strong>). In the addresses on this page, <code>&lt;server&gt;</code> is the server&#39;s name or IP with the port — <code>192.168.1.42:5154</code>, say — and <a href="./server-addresses">Reaching the server: name or IP</a> says which one to give each device. <code>{eventId}</code> is the event&#39;s folder name, like <code>2026-11-10.01</code>.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What</th><th>Address or port</th><th>Direction</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Every API address, with its parameters</strong></td><td><code>/swagger</code> (OpenAPI: <code>/swagger/v1/swagger.json</code>)</td><td>Browsers connect in</td><td><a href="#the-full-list-swagger">above</a></td></tr><tr><td>Screens for people</td><td><code>/manager</code>, <code>/rego</code>, <code>/</code>, <code>/kiosk</code>, <code>/screen/…</code>, <code>/info</code>, <code>/commentary</code></td><td>Browsers connect in</td><td><a href="#screens-for-people">below</a></td></tr><tr><td>Results, start list and entry list files</td><td><code>GET /manager/api/ResultsExport/{eventId}/…</code></td><td>Other software fetches</td><td><a href="#files-other-software-can-fetch">below</a></td></tr><tr><td>AI assistants (MCP)</td><td><code>/manager/mcp</code> — <strong>off by default</strong></td><td>An AI app connects in</td><td><a href="./ai-assistants-mcp">AI assistants (MCP)</a></td></tr><tr><td>The HTTPS certificate</td><td><code>/manager/api/https/ca.crt</code></td><td>Devices download it</td><td><a href="./https-and-certificates#trusting-the-certificate">HTTPS and certificates</a></td></tr><tr><td>This user guide</td><td><code>/docs/user/</code></td><td>Browsers connect in</td><td>—</td></tr><tr><td>Radio punches in (SIRAP)</td><td>TCP, the <strong>Listen port</strong> (default 10000)</td><td>Another system connects in</td><td><a href="./../running-the-event/radio-punches#forwarding-and-receiving-punches">Forwarding and receiving punches</a></td></tr><tr><td>Radio punches out (SIRAP or OE12)</td><td>TCP, to the host and port you set</td><td>Manager connects out</td><td><a href="./../running-the-event/radio-punches#forwarding-and-receiving-punches">Forwarding and receiving punches</a></td></tr><tr><td>Live results file</td><td>A folder, not a network address</td><td>Manager writes a file</td><td><a href="./../event-setup/create-event#live-export">Live export</a></td></tr><tr><td>liveresultat, the meshO cloud, Eventor, ANNE, ROC</td><td>Their servers</td><td>Manager connects out</td><td><a href="#connections-manager-makes-itself">below</a></td></tr></tbody></table><h2 id="screens-for-people" tabindex="-1">Screens for people <a class="header-anchor" href="#screens-for-people" aria-label="Permalink to &quot;Screens for people&quot;">​</a></h2><p>Each of these is listed with a copy button and a QR code under <strong>Settings → Server → Access links</strong>, except the arena screens, which have their own links on the <strong>Screens</strong> page.</p><table tabindex="0"><thead><tr><th>Screen</th><th>Address</th><th>Page</th></tr></thead><tbody><tr><td>Manager</td><td><code>http://&lt;server&gt;/manager</code></td><td>—</td></tr><tr><td>Registration desk</td><td><code>http://&lt;server&gt;/rego</code></td><td><a href="./../running-the-event/registration-desk">Registration desk</a></td></tr><tr><td>Spectator site</td><td><code>http://&lt;server&gt;/</code></td><td><a href="./../screens/spectator-site-and-kiosk">Spectator site and kiosk</a></td></tr><tr><td>Kiosk</td><td><code>http://&lt;server&gt;/kiosk</code></td><td><a href="./../screens/spectator-site-and-kiosk">Spectator site and kiosk</a></td></tr><tr><td>Arena screens</td><td><code>http://&lt;server&gt;/screen/&lt;screen-id&gt;?eventId={eventId}</code></td><td><a href="./../screens/tv-screens">TV screens</a></td></tr><tr><td>Info screens</td><td><code>http://&lt;server&gt;/info</code></td><td><a href="./../screens/info-screens">Event info screens</a></td></tr><tr><td>Commentary</td><td><code>http://&lt;server&gt;/commentary</code></td><td><a href="./../screens/commentary">Commentary</a></td></tr></tbody></table><h2 id="files-other-software-can-fetch" tabindex="-1">Files other software can fetch <a class="header-anchor" href="#files-other-software-can-fetch" aria-label="Permalink to &quot;Files other software can fetch&quot;">​</a></h2><p>The entry list, start list and results that the <strong>Export</strong> menus save are also plain <code>GET</code> addresses, so a results website or a script can fetch them itself, as often as it likes:</p><table tabindex="0"><thead><tr><th>Document</th><th>IOF XML</th><th>Orienteering JSON</th><th>CSV</th></tr></thead><tbody><tr><td>Results</td><td><code>/manager/api/ResultsExport/{eventId}/iof-xml</code></td><td><code>…/{eventId}/json</code></td><td>—</td></tr><tr><td>Start list</td><td><code>…/{eventId}/iof-startlist-xml</code></td><td><code>…/{eventId}/startlist-json</code></td><td><code>…/{eventId}/startlist-csv</code></td></tr><tr><td>Entry list</td><td><code>…/{eventId}/iof-entrylist-xml</code></td><td><code>…/{eventId}/entrylist-json</code></td><td><code>…/{eventId}/entrylist-csv</code></td></tr><tr><td>Start blocks</td><td>—</td><td><code>…/{eventId}/startblocks-json</code></td><td><code>…/{eventId}/startblocks-csv</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> results.xml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://localhost:5154/manager/api/ResultsExport/2026-11-10.01/iof-xml?includeDidNotStart=true&quot;</span></span></code></pre></div><p>They take the same choices as the <strong>Publish options</strong> dialog, as query parameters:</p><table tabindex="0"><thead><tr><th>Query parameter</th><th>Applies to</th><th>Meaning</th></tr></thead><tbody><tr><td><code>kind</code></td><td>all but the start blocks</td><td><code>Relay</code> or <code>Individual</code>. <strong>Required</strong> on an event that has both kinds of class: a file never mixes them.</td></tr><tr><td><code>classIds</code></td><td>all</td><td>Comma-separated class ids. Left out, every class.</td></tr><tr><td><code>countries</code></td><td>results</td><td>Comma-separated country codes; <code>-</code> is everyone with no country. Left out, every country.</td></tr><tr><td><code>includeDidNotStart</code></td><td>results</td><td><code>true</code> keeps the competitors marked DNS in the file.</td></tr><tr><td><code>acceptUnsettled</code></td><td>results</td><td><code>true</code> publishes even while someone has no settled result, as <strong>Ignore and continue</strong> does. Without it, the results are refused (HTTP 409, naming who is unsettled) until everybody has one.</td></tr><tr><td><code>combine</code>, <code>omitOrganisationIds</code></td><td>IOF XML results</td><td>The <strong>IOF XML options</strong>: classes combined for the World Ranking, and leaving out organisation ids. See <a href="./../after-the-event/exports#combining-classes-for-the-world-ranking-iof-xml">Combining classes for the World Ranking</a>.</td></tr><tr><td><code>includePrivateFields</code></td><td>JSON results</td><td>Adds birth year and sex. Needs a signed-in operator.</td></tr></tbody></table><p>The JSON format, what each parameter does in detail, and the schema to validate against are in <a href="./../advanced/orienteering-json#from-the-api">Orienteering JSON (OJSON)</a>. What a results file says about each status is in <a href="./status-and-race-time#what-an-exported-results-file-contains">What an exported results file contains</a>.</p><p>Things to know:</p><ul><li><strong>These answer without the access PIN</strong>, as every read does on a Manager running on your own computer — so anyone who can reach the server can fetch them. Two things do need a signed-in session where a <a href="./settings#access-protection">PIN</a> is set: <code>includePrivateFields</code>, and the <strong>results</strong> while a class is <a href="./../event-setup/results-quarantine">held back in quarantine</a>.</li><li><strong>To feed a live-results system that watches a folder</strong>, such as LiveResults EmmaClient, use the <a href="./../event-setup/create-event#live-export">Live export</a> instead: it writes the results file every few seconds or minutes on its own, including runners still on course.</li><li><strong>Nothing pushes to you.</strong> There is no webhook: software that wants the latest results fetches again.</li></ul><h2 id="reading-the-event-from-another-program" tabindex="-1">Reading the event from another program <a class="header-anchor" href="#reading-the-event-from-another-program" aria-label="Permalink to &quot;Reading the event from another program&quot;">​</a></h2><p>To have another program <em>read the event and answer questions about it</em> rather than fetch a file, connect it as an <a href="./ai-assistants-mcp">AI assistant over MCP</a>: that is the interface designed for it, and it is switched off until you turn it on.</p><h2 id="connections-manager-makes-itself" tabindex="-1">Connections Manager makes itself <a class="header-anchor" href="#connections-manager-makes-itself" aria-label="Permalink to &quot;Connections Manager makes itself&quot;">​</a></h2><p>Some features have Manager connect out to someone else&#39;s server, rather than the other way round. Each is off until you set it up:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Connects to</th><th>Page</th></tr></thead><tbody><tr><td>Live results online</td><td>liveresultat.orientering.se, and the meshO cloud (events.mesho.live)</td><td><a href="./../running-the-event/publishing-live-results">Publishing live results online</a></td></tr><tr><td>Eventor</td><td>Your federation&#39;s Eventor, with your organisation&#39;s API key</td><td><a href="./../event-setup/create-event-from-eventor">Create an event from Eventor</a>, <a href="./../after-the-event/exports#uploading-to-eventor">Uploading to Eventor</a></td></tr><tr><td>ANNE</td><td>ANNE, the Austrian orienteering portal — the real one or its test copy, as Settings → ANNE says</td><td><a href="./../event-setup/import-event-data#importing-from-anne">Importing from ANNE</a>, <a href="./../after-the-event/exports#uploading-to-anne">Uploading to ANNE</a></td></tr><tr><td>ROC radio controls</td><td>The ROC server, to fetch punches</td><td><a href="./../running-the-event/connecting-prime-and-radios#radio-controls-that-report-to-roc">Radio controls that report to ROC</a></td></tr><tr><td>Radio punch forwarding</td><td>The TCP host and port you set</td><td><a href="./../running-the-event/radio-punches#forwarding-and-receiving-punches">Forwarding and receiving punches</a></td></tr><tr><td>Built-in assistant</td><td>meshO&#39;s assistant service</td><td><a href="./built-in-assistant">Built-in assistant</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./server-addresses">Reaching the server: name or IP</a> — which address to give each device</li><li><a href="./https-and-certificates">HTTPS and certificates</a> — the secure port, and when you need it</li><li><a href="./multi-operator-setup">Multi-operator setup</a> — what the access PIN protects</li><li><a href="./../after-the-event/exports">Exporting data</a> — the same files, from the menus</li><li><a href="./../advanced/orienteering-json">Orienteering JSON (OJSON)</a></li><li><a href="./ai-assistants-mcp">AI assistants (MCP)</a></li></ul>',28)])])}const u=t(n,[["render",o]]);export{p as __pageData,u as default};
